var shortestCompletingWord = function(licensePlate, words) {
    const target = new Array(26).fill(0);
    for (let i = 0; i < licensePlate.length; i++) {
        const c = licensePlate[i].toLowerCase();
        if (c >= 'a' && c <= 'z') target[c.charCodeAt(0) - 97]++;
    }
    let bestWord = null;
    for (const word of words) {
        const count = new Array(26).fill(0);
        for (let i = 0; i < word.length; i++) {
            count[word.charCodeAt(i) - 97]++;
        }
        let ok = true;
        for (let i = 0; i < 26; i++) {
            if (count[i] < target[i]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            if (bestWord === null || word.length < bestWord.length) {
                bestWord = word;
            }
        }
    }
    return bestWord;
};
